import{_ as a,o,c as t,a2 as b}from"./chunks/framework.DN6PggGS.js";const p=JSON.parse('{"title":"Dubbo","description":"Dubbo：链接：https://note.youdao.com/ynoteshare/index.html?id=ca746f44f16b862e3189e5f24b3a8e64&type=note&time=1685805324275","frontmatter":{},"headers":[],"relativePath":"framework/dubbo/index.md","filePath":"framework/dubbo/index.md"}'),r={name:"framework/dubbo/index.md"};function d(i,e,n,h,l,u){return o(),t("div",null,[...e[0]||(e[0]=[b('<h1 id="dubbo" tabindex="-1">Dubbo <a class="header-anchor" href="#dubbo" aria-label="Permalink to &quot;Dubbo&quot;">​</a></h1><h2 id="dubbo底层实现原理" tabindex="-1">Dubbo底层实现原理 <a class="header-anchor" href="#dubbo底层实现原理" aria-label="Permalink to &quot;Dubbo底层实现原理&quot;">​</a></h2><p>链接：<a href="https://note.youdao.com/ynoteshare/index.html?id=ca746f44f16b862e3189e5f24b3a8e64&amp;type=note&amp;_time=1685805324275" target="_blank" rel="noreferrer">https://note.youdao.com/ynoteshare/index.html?id=ca746f44f16b862e3189e5f24b3a8e64&amp;type=note&amp;_time=1685805324275</a></p><h2 id="dubbo3-0新特性" tabindex="-1">Dubbo3.0新特性 <a class="header-anchor" href="#dubbo3-0新特性" aria-label="Permalink to &quot;Dubbo3.0新特性&quot;">​</a></h2><h3 id="dubbo协议" tabindex="-1">dubbo协议 <a class="header-anchor" href="#dubbo协议" aria-label="Permalink to &quot;dubbo协议&quot;">​</a></h3><p>dubbo协议由于请求中没有多余的无用的字节，都是必要的字节，因此性能会更好，并且每个Dubbo请求和响应中都有一个请求ID，这样可以基于一个Socket连接同时发送多个Dubbo请求，不用担心请求和响应对不上，所以dubbo协议成为了Dubbo框架中的默认协议。</p><p>但是dubbo协议一旦涉及到跨RPC框架，比如一个Dubbo服务要调用gRPC服务，就比较麻烦了。因为发一个dubbo协议的请求给一个gRPC服务，gRPC服务只会按照gRPC的格式来解析字节流，最终肯定会解析不成功的。</p><p>dubbo协议虽好，但是不够通用，所以这就出现了Triple协议，Triple协议是基于HTTP2，没有性能问题，另外HTTP协议非常通用，兼容起来也比较简单，而且还有很多额外的功能，比如流式调用。</p><h3 id="triple协议" tabindex="-1">Triple协议 <a class="header-anchor" href="#triple协议" aria-label="Permalink to &quot;Triple协议&quot;">​</a></h3><h2 id="dubbo服务注册与引入底层原理" tabindex="-1">Dubbo服务注册与引入底层原理 <a class="header-anchor" href="#dubbo服务注册与引入底层原理" aria-label="Permalink to &quot;Dubbo服务注册与引入底层原理&quot;">​</a></h2><p>参考链接：<a href="https://note.youdao.com/ynoteshare/index.html?id=bbeb46c842c84cfcdbf1d1f040fe40c7&amp;type=note&amp;_time=1685977459844" target="_blank" rel="noreferrer">https://note.youdao.com/ynoteshare/index.html?id=bbeb46c842c84cfcdbf1d1f040fe40c7&amp;type=note&amp;_time=1685977459844</a></p><p>服务导出与服务引入的流程图：<a href="https://www.processon.com/view/link/62c441e80791293dccaebded" target="_blank" rel="noreferrer">https://www.processon.com/view/link/62c441e80791293dccaebded</a></p><h3 id="服务导出" tabindex="-1">服务导出 <a class="header-anchor" href="#服务导出" aria-label="Permalink to &quot;服务导出&quot;">​</a></h3><h3 id="服务引入" tabindex="-1">服务引入 <a class="header-anchor" href="#服务引入" aria-label="Permalink to &quot;服务引入&quot;">​</a></h3><h2 id="dubbo服务调用底层原理" tabindex="-1">Dubbo服务调用底层原理 <a class="header-anchor" href="#dubbo服务调用底层原理" aria-label="Permalink to &quot;Dubbo服务调用底层原理&quot;">​</a></h2><h3 id="http2原理解析" tabindex="-1">Http2原理解析 <a class="header-anchor" href="#http2原理解析" aria-label="Permalink to &quot;Http2原理解析&quot;">​</a></h3><p>Http2可以支持同时发在一个socket上送多个请求。</p><ul><li>帧长度</li><li>帧类型</li></ul>',18)])])}const s=a(r,[["render",d]]);export{p as __pageData,s as default};
